/* Beyond One and the brands' logos for the decks (made by js/make_brand.py from assets/brand): the picture's bytes (PNG; GIF for
   the moving stacked logos, which PowerPoint plays) with their size. */
'use strict';
const BoLogos = (() => {
const b = s => { const t = atob(s), u = new Uint8Array(t.length); for (let i = 0; i < t.length; i++) u[i] = t.charCodeAt(i); return u; };
const L = {
  stackedBlack: { w: 300, h: 457, type: 'png', b64: '' },
  stackedWhite: { w: 300, h: 457, type: 'png', b64: '' },
  black: { w: 560, h: 156, type: 'png', b64: '' },
  white: { w: 560, h: 156, type: 'png', b64: '' },
  mark: { w: 160, h: 160, type: 'png', b64: '' },
  virgin: { w: 480, h: 270, type: 'png', b64: '' },
  friendi: { w: 480, h: 277, type: 'png', b64: '' },
  fpay: { w: 480, h: 277, type: 'png', b64: '' },
  stackedBlackAnim: { w: 300, h: 457, type: 'gif', b64: '' },
  stackedWhiteAnim: { w: 300, h: 457, type: 'gif', b64: '' },
  markNavyAnim: { w: 60, h: 60, type: 'gif', b64: '' },
};
// each picture decoded once and then the same bytes every time, so a deck keeps it once however many slides show it
const out = {}; for (const k of Object.keys(L)) { let u = null; out[k] = { w: L[k].w, h: L[k].h, get png() { return u || (u = b(L[k].b64)); }, type: L[k].type, dataUrl: 'data:image/' + L[k].type + ';base64,' + L[k].b64 }; }
return out;
})();
if (typeof module !== 'undefined') module.exports = BoLogos;
